import logging
import os

import discord
from discord import app_commands
from discord.ext import commands

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s: %(message)s",
)
log = logging.getLogger("showcasebot")


class Bot(commands.Bot):
    def __init__(self) -> None:
        intents = discord.Intents.default()
        intents.members = True
        super().__init__(command_prefix="!", intents=intents)

    async def setup_hook(self) -> None:
        await self.tree.sync()
        log.info("Commands synced globally.")

    async def on_ready(self) -> None:
        log.info(f"{self.user} is online")

    async def on_member_join(self, member: discord.Member) -> None:
        channel = member.guild.system_channel
        if channel is not None:
            await channel.send(f"Welcome to {member.guild.name}, {member.mention}!")


bot = Bot()


@bot.tree.command(name="ping", description="Answer with pong")
async def cmd_ping(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"Pong! Hello {interaction.user.mention}")


@bot.tree.command(name="whereami", description="Tell you where you are right now")
async def cmd_whereami(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"You are {interaction.user.mention} in {_channel_text(interaction.channel)} on {interaction.guild.name if interaction.guild else 'DM'}!")


@bot.tree.command(name="secret", description="A private reply only you can see")
async def cmd_secret(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"Shh, {interaction.user.mention} — only you can see this.", ephemeral=True)


@bot.tree.command(name="rules", description="rules")
async def cmd_rules(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"Be kind, {interaction.user.mention} — this is {interaction.guild.name if interaction.guild else 'DM'}!")


@bot.tree.error
async def on_app_command_error(interaction: discord.Interaction,
                               error: app_commands.AppCommandError) -> None:
    log.warning("Command failed: %s", error)
    message = "Sorry, that command hit a problem. Try again."
    try:
        if interaction.response.is_done():
            await interaction.followup.send(message, ephemeral=True)
        else:
            await interaction.response.send_message(message, ephemeral=True)
    except discord.HTTPException:
        log.warning("Could not answer the failed command.")


def _channel_text(channel) -> str:
    """The channel as text: its mention, its name, or ""."""
    if channel is None:
        return ""
    return getattr(channel, "mention", None) or str(channel)


def main() -> None:
    token = os.environ.get("DISCORD_TOKEN")
    if not token:
        raise SystemExit("set the DISCORD_TOKEN environment variable")
    bot.run(token)


if __name__ == "__main__":
    main()
